/**
 * JP 100plus新品落地页
 * 因时间紧迫，且引用旧组件，故采用旧的开发范式
 */

import './index.less'

// 12th 留言表单
import { CommentForm } from '../../olight/sections/form/index'

// 12th 留言列表
import { Comments } from '../../jackery-12th-anniversary/sections/jky-12th-comments/index'

document.addEventListener('DOMContentLoaded', function () {
  new CommentForm({el: '.jky-12th-form'})
  new Comments()

  // 渐变出现
   const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
          if (entry.isIntersecting) {
            // 元素进入视窗,触发动画
            entry.target.classList.add('jky-up-animation');
          }
      });
  });

  // 开始观察目标元素
  const slideups = document.querySelectorAll('.jky-up')
  if (slideups && slideups.length) {
      slideups.forEach(item => {
          observer.observe(item); 
      })
  }
})